-- Generated by local CLI then ordered after C/D foundations. Customer reply
-- credits only: native cost ledger, owner trial lifetime cap and finance remain.
begin;
create table private.master_ai_cycles(
 id uuid primary key references private.master_subscription_activation(receipt_id),company_id uuid not null references public.companies(id),subscription_id uuid not null references public.billing_subscriptions(id),
 initial_plan_version_id uuid not null references public.billing_plan_versions(id),current_plan_version_id uuid not null references public.billing_plan_versions(id),
 starts_at timestamptz not null,expires_at timestamptz not null,base_cap integer not null check(base_cap in(500,1500)),
 created_at timestamptz not null default clock_timestamp(),check(isfinite(starts_at) and isfinite(expires_at) and expires_at>starts_at)
);
create index master_ai_company_cycle on private.master_ai_cycles(company_id,starts_at desc);
create table private.master_ai_credit_grants(
 id uuid primary key default gen_random_uuid(),cycle_id uuid not null references private.master_ai_cycles(id),kind text not null check(kind in('base','topup','compensation')),
 source_key text not null unique,units bigint not null check(units>0),forfeited bigint not null default 0 check(forfeited>=0 and forfeited<=units),replaced boolean not null default false,
 expires_at timestamptz not null,created_at timestamptz not null default clock_timestamp()
);
create index master_ai_grants_cycle_kind on private.master_ai_credit_grants(cycle_id,kind);
create table private.master_ai_reply_slots(
 job_id uuid primary key references public.whatsapp_inbound_jobs(id),cycle_id uuid not null references private.master_ai_cycles(id),grant_id uuid not null references private.master_ai_credit_grants(id),
 company_id uuid not null references public.companies(id),channel text not null check(channel='whatsapp'),state text not null check(state in('held','accepted','released','unknown')),
 accepted_at timestamptz,native_intent_id uuid references public.whatsapp_send_intents(id),provider_receipt text unique,ai_attempt_id uuid references public.ai_usage_ledger(id),
 created_at timestamptz not null default clock_timestamp(),check(state<>'accepted' or accepted_at is not null and provider_receipt is not null and native_intent_id is not null and ai_attempt_id is not null)
);
create index master_ai_slots_cycle_state on private.master_ai_reply_slots(cycle_id,state,accepted_at);
create index master_ai_slots_grant_state on private.master_ai_reply_slots(grant_id,state);
-- Cost categories bind at the native model reservation, independently of later
-- reply release/retry or display-message persistence. Native costs stay native.
create table private.master_ai_attempt_credit_binding(attempt_id uuid primary key references public.ai_usage_ledger(id),job_id uuid not null references public.whatsapp_inbound_jobs(id),cycle_id uuid not null references private.master_ai_cycles(id),company_id uuid not null references public.companies(id),grant_id uuid not null references private.master_ai_credit_grants(id),created_at timestamptz not null default clock_timestamp());
create index master_ai_attempt_cycle on private.master_ai_attempt_credit_binding(cycle_id,company_id);
create table private.master_ai_credit_events(id bigint generated always as identity primary key,cycle_id uuid not null references private.master_ai_cycles(id),kind text not null,source_key text not null unique,detail jsonb not null default '{}',created_at timestamptz not null default clock_timestamp());
create table private.master_ai_usage_notices(cycle_id uuid not null references private.master_ai_cycles(id),threshold integer not null check(threshold in(80,100)),created_at timestamptz not null default clock_timestamp(),state text not null default 'pending' check(state in('pending','sent')),primary key(cycle_id,threshold));
-- No approved price/size or expiry policy exists. No seed and no public writer.
create table private.master_ai_topup_catalog(sku text primary key,units bigint not null check(units>0),amount_baisa bigint not null check(amount_baisa>0),plan_version_id uuid not null references public.billing_plan_versions(id),approval_reference text not null check(length(btrim(approval_reference))>0),legal_reference text not null check(length(btrim(legal_reference))>0),enabled boolean not null default false);
create table private.master_ai_topup_contracts(order_id uuid primary key references public.billing_orders(id),cycle_id uuid not null references private.master_ai_cycles(id),sku text not null references private.master_ai_topup_catalog(sku),expires_at timestamptz not null,accepted_by uuid not null references auth.users(id),accepted_at timestamptz not null,terms_reference text not null check(length(btrim(terms_reference))>0));
create table private.master_ai_evidence_contracts(source text primary key check(source in('velora','meta')),approval_reference text not null check(length(btrim(approval_reference))>0),enabled boolean not null default false);
create table private.master_ai_credit_legal(singleton boolean primary key default true check(singleton),compensation_expiry_reference text);
insert into private.master_ai_credit_legal(singleton) values(true);
create table private.master_ai_observations(id uuid primary key default gen_random_uuid(),cycle_id uuid not null references private.master_ai_cycles(id),source text not null references private.master_ai_evidence_contracts(source),evidence_reference text not null unique,
 kind text not null check(kind in('healthy','outage','incomplete')),channels text[] not null,starts_at timestamptz not null,ends_at timestamptz not null,verified_at timestamptz not null default clock_timestamp(),
 check(isfinite(starts_at) and isfinite(ends_at) and ends_at>starts_at),check(length(btrim(evidence_reference))>0));
create index master_ai_observation_cycle_kind on private.master_ai_observations(cycle_id,kind,starts_at,ends_at);
create table private.master_ai_compensation_assessments(observation_id uuid primary key references private.master_ai_observations(id),cycle_id uuid not null references private.master_ai_cycles(id),estimated_units numeric not null,awarded_units bigint not null,outcome text not null,created_at timestamptz not null default clock_timestamp());
do $$declare t text;begin foreach t in array array['master_ai_cycles','master_ai_credit_grants','master_ai_reply_slots','master_ai_attempt_credit_binding','master_ai_credit_events','master_ai_usage_notices','master_ai_topup_catalog','master_ai_topup_contracts','master_ai_evidence_contracts','master_ai_credit_legal','master_ai_observations','master_ai_compensation_assessments'] loop execute format('alter table private.%I enable row level security',t);execute format('revoke all on private.%I from public,anon,authenticated,service_role',t);end loop;end;$$;

create function private.master_ai_cycle_period(cid uuid) returns timestamptz language sql volatile security definer set search_path='' as $$
 select case when (select enabled from private.master_activation_policy where singleton) then
  (select a.subscription_started_at from private.master_subscription_activation a where a.company_id=cid and private.master_activation_receipt_current(a.receipt_id) order by a.subscription_started_at desc nulls last,a.receipt_id limit 1)
 else private.wa_worker_month() end;
$$;
create function private.master_capture_ai_cycle_locked(cid uuid,rid uuid,p_upgrade boolean default false) returns uuid
language plpgsql security definer set search_path='' as $$
declare a private.master_subscription_activation;g record;cap integer;code text;
begin
 select * into a from private.master_subscription_activation where receipt_id=rid and company_id=cid;
 if a.receipt_id is null or a.subscription_started_at is null or a.expires_at is null or (not p_upgrade and not private.master_activation_receipt_current(rid)) then return null;end if;
 select * into g from private.billing_proven_entitlement_grants where id=rid and company_id=cid and subscription_id=a.subscription_id and provider_environment='live';
 if g.id is null or g.applied_paid_through is distinct from a.receipt_paid_through then return null;end if;
 select case when p.code='noor_basic' and v.limits->>'automated_outbound_per_month'='500' then 500 when p.code='noor_premium' and v.limits->>'automated_outbound_per_month'='1500' then 1500 end,p.code into cap,code
  from public.billing_plan_versions v join public.billing_plans p on p.id=v.plan_id where v.id=g.plan_version_id and v.status in('published','retired');
 if cap is null then return null;end if;
 -- Calendar-era reservations are immutable. Never silently give a fresh quota
 -- over existing unaccounted usage; a separately reviewed import is required.
 if exists(select 1 from public.whatsapp_inbound_jobs j where j.company_id=cid and j.usage_subscription_id=a.subscription_id
  and j.created_at>=a.subscription_started_at and j.created_at<a.expires_at and j.usage_status in('reserved','accepted','unknown')
  and not exists(select 1 from private.master_ai_reply_slots s where s.job_id=j.id)) then return null;end if;
 insert into private.master_ai_cycles(id,company_id,subscription_id,initial_plan_version_id,current_plan_version_id,starts_at,expires_at,base_cap)
 values(rid,cid,a.subscription_id,g.plan_version_id,g.plan_version_id,a.subscription_started_at,a.expires_at,cap) on conflict do nothing;
 if not exists(select 1 from private.master_ai_cycles where id=rid and company_id=cid and subscription_id=a.subscription_id and starts_at=a.subscription_started_at and expires_at=a.expires_at) then return null;end if;
 insert into private.master_ai_credit_grants(cycle_id,kind,source_key,units,expires_at) values(rid,'base','base:'||rid,cap,a.expires_at) on conflict(source_key) do nothing;
 insert into private.master_ai_credit_events(cycle_id,kind,source_key,detail) values(rid,'cycle_captured','capture:'||rid,jsonb_build_object('planVersionId',g.plan_version_id,'baseCap',cap)) on conflict do nothing;
 return rid;
end;$$;
create function public.master_capture_ai_cycle(p_company_id uuid,p_receipt_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare rid uuid;begin
 if current_setting('role',true)<>'service_role' then raise exception 'SERVER_ROLE_REQUIRED' using errcode='42501';end if;
 perform 1 from public.companies where id=p_company_id for no key update;perform 1 from public.billing_subscriptions where company_id=p_company_id and environment='live' for no key update;
 rid:=private.master_capture_ai_cycle_locked(p_company_id,p_receipt_id);return case when rid is null then jsonb_build_object('ok',false,'code','PAID_CYCLE_PROOF_REQUIRED') else jsonb_build_object('ok',true,'data',jsonb_build_object('cycleId',rid)) end;
end;$$;

create function private.master_sync_ai_reply(p_job_id uuid) returns void language plpgsql security definer set search_path='' as $$
declare j public.whatsapp_inbound_jobs;i public.whatsapp_send_intents;s private.master_ai_reply_slots;available bigint;used bigint;
begin
 select * into s from private.master_ai_reply_slots where job_id=p_job_id;if s.job_id is null then return;end if;
 select * into j from public.whatsapp_inbound_jobs where id=p_job_id and company_id=s.company_id;
 if j.usage_status='accepted' then
  select * into i from public.whatsapp_send_intents where id=j.send_intent_id and company_id=j.company_id and original_job_id=j.id;
  if i.id is null or i.sender_kind<>'assistant' or i.response_kind is not null or i.outcome<>'accepted' or nullif(btrim(i.wa_message_id),'') is null
   or not exists(select 1 from public.whatsapp_messages m where id=j.message_id and company_id=j.company_id and conversation_id=i.conversation_id and direction='inbound' and sender='customer')
   or not exists(select 1 from public.ai_usage_ledger a where id=j.staged_ai_attempt_id and company_id=j.company_id and worker_job_id=j.id and usage_mode='company_live' and status='success' and response_text=i.body and source_citations=j.staged_citations and automation_generation=j.expected_automation_generation)
  then raise exception 'CYCLE_ACCEPTED_NATIVE_PROOF_REQUIRED';end if;
  if s.state='accepted' then if s.provider_receipt<>i.wa_message_id then raise exception 'CYCLE_RECEIPT_IMMUTABLE';end if;return;end if;
  update private.master_ai_reply_slots set state='accepted',accepted_at=coalesce(i.acceptance_observed_at,j.completed_at,clock_timestamp()),native_intent_id=i.id,provider_receipt=i.wa_message_id,ai_attempt_id=j.staged_ai_attempt_id where job_id=j.id;
  select coalesce(sum(units-forfeited),0) into available from private.master_ai_credit_grants where cycle_id=s.cycle_id;
  select count(*) into used from private.master_ai_reply_slots where cycle_id=s.cycle_id and state='accepted';
  if available>0 then insert into private.master_ai_usage_notices(cycle_id,threshold) select s.cycle_id,t from unnest(array[80,100]) t where used*100>=available*t on conflict do nothing;end if;
 elsif s.state<>'accepted' and j.usage_status in('released','unknown') then update private.master_ai_reply_slots set state=j.usage_status where job_id=j.id;end if;
end;$$;
create function private.master_sync_ai_reply_trigger() returns trigger language plpgsql security definer set search_path='' as $$begin perform private.master_sync_ai_reply(new.id);return new;end;$$;
create trigger master_ai_native_usage_sync after update of usage_status on public.whatsapp_inbound_jobs for each row execute function private.master_sync_ai_reply_trigger();
create function private.master_ai_attempt_binding_trigger() returns trigger language plpgsql security definer set search_path='' as $$declare s private.master_ai_reply_slots;b private.master_ai_attempt_credit_binding;begin
 if tg_op='UPDATE' then
  select * into b from private.master_ai_attempt_credit_binding where attempt_id=old.id;
  if b.attempt_id is not null and row(new.id,new.company_id,new.worker_job_id,new.usage_mode) is distinct from row(old.id,old.company_id,old.worker_job_id,old.usage_mode) then raise exception 'CYCLE_COST_BINDING_IMMUTABLE';end if;return new;
 end if;
 if not (select enabled from private.master_activation_policy where singleton) or new.usage_mode<>'company_live' then return new;end if;
 select * into s from private.master_ai_reply_slots where job_id=new.worker_job_id and company_id=new.company_id and state='held';
 if new.status<>'reserved' or s.job_id is null or not exists(select 1 from private.master_ai_cycles where id=s.cycle_id and starts_at<=clock_timestamp() and expires_at>clock_timestamp()) then raise exception 'CYCLE_MODEL_RESERVATION_REQUIRED';end if;
 insert into private.master_ai_attempt_credit_binding(attempt_id,job_id,cycle_id,company_id,grant_id) values(new.id,s.job_id,s.cycle_id,s.company_id,s.grant_id);
 return new;
end;$$;
create trigger master_ai_native_cost_binding after insert or update of company_id,worker_job_id,usage_mode on public.ai_usage_ledger for each row execute function private.master_ai_attempt_binding_trigger();

alter function public.whatsapp_reserve_job_usage(uuid,uuid) set schema private;
alter function private.whatsapp_reserve_job_usage(uuid,uuid) rename to master_pre_cycle_reserve_usage;
revoke all on function private.master_pre_cycle_reserve_usage(uuid,uuid) from public,anon,authenticated,service_role;
create function public.whatsapp_reserve_job_usage(p_job_id uuid,p_claim_token uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare j public.whatsapp_inbound_jobs;rid uuid;credit uuid;slot private.master_ai_reply_slots;proof jsonb;
begin
 if current_setting('role',true)<>'service_role' then raise exception 'SERVER_ROLE_REQUIRED' using errcode='42501';end if;
 if not (select enabled from private.master_activation_policy where singleton) then return private.master_pre_cycle_reserve_usage(p_job_id,p_claim_token);end if;
 proof:=private.whatsapp_answer_profile(p_job_id,p_claim_token);if proof->>'ok' is distinct from 'true' then return proof;end if;
 j:=private.wa_worker_lock(p_job_id,p_claim_token);if j.id is null then return jsonb_build_object('ok',false,'code','claim_or_automation_rejected');end if;
 if public.billing_read_company_operational_entitlement(j.company_id)->'active' is distinct from 'true'::jsonb or not private.master_activation_can_operate(j.company_id) then return jsonb_build_object('ok',false,'code','subscription_inactive');end if;
 select a.receipt_id into rid from private.master_subscription_activation a where a.company_id=j.company_id and private.master_activation_receipt_current(a.receipt_id) order by a.subscription_started_at desc nulls last,a.receipt_id limit 1;
 rid:=private.master_capture_ai_cycle_locked(j.company_id,rid);if rid is null then return jsonb_build_object('ok',false,'code','PAID_CYCLE_PROOF_REQUIRED');end if;
 if not exists(select 1 from private.master_ai_cycles where id=rid and starts_at<=clock_timestamp() and expires_at>clock_timestamp()) then return jsonb_build_object('ok',false,'code','subscription_inactive');end if;
 select * into slot from private.master_ai_reply_slots where job_id=j.id;
 if slot.job_id is not null then
  if slot.cycle_id<>rid or slot.company_id<>j.company_id or slot.state in('accepted','unknown') then return jsonb_build_object('ok',false,'code','usage_already_final_or_unknown');end if;
  if slot.state='held' then return jsonb_build_object('ok',true,'reused',true,'can_dispatch',false,'status','reserved');end if;
  -- Release is safe only when the native worker has no accepted/unknown intent.
 end if;
 if j.send_intent_id is not null and exists(select 1 from public.whatsapp_send_intents where id=j.send_intent_id and outcome<>'ready') then return jsonb_build_object('ok',false,'code','send_outcome_requires_review');end if;
 if slot.job_id is null and j.usage_status is not null then return jsonb_build_object('ok',false,'code','LEGACY_RESERVATION_REVIEW_REQUIRED');end if;
 select g.id into credit from private.master_ai_credit_grants g where g.cycle_id=rid and not g.replaced and g.expires_at>clock_timestamp()
  and g.units-g.forfeited>(select count(*) from private.master_ai_reply_slots x where x.grant_id=g.id and x.state in('held','accepted','unknown'))
 order by case g.kind when 'base' then 0 when 'topup' then 1 else 2 end,g.created_at,g.id limit 1;
 if credit is null then return jsonb_build_object('ok',false,'code','usage_limit_reached');end if;
 insert into private.master_ai_reply_slots(job_id,cycle_id,grant_id,company_id,channel,state) values(j.id,rid,credit,j.company_id,'whatsapp','held')
  on conflict(job_id) do update set grant_id=excluded.grant_id,state='held';
 update public.whatsapp_inbound_jobs set usage_status='reserved',usage_period_start=(select starts_at from private.master_ai_cycles where id=rid),usage_subscription_id=(select subscription_id from private.master_ai_cycles where id=rid) where id=j.id;
 return jsonb_build_object('ok',true,'reused',false,'can_dispatch',true,'status','reserved','cycleId',rid);
end;$$;

create function public.master_apply_cycle_upgrade(p_company_id uuid,p_receipt_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare g record;b jsonb;c private.master_ai_cycles;rid uuid;target uuid;
begin
 if current_setting('role',true)<>'service_role' then raise exception 'SERVER_ROLE_REQUIRED' using errcode='42501';end if;
 if to_regclass('private.master_checkout_upgrades') is null then return jsonb_build_object('ok',false,'code','UPGRADE_PROOF_REQUIRED');end if;
 perform 1 from public.companies where id=p_company_id for no key update;perform 1 from public.billing_subscriptions where company_id=p_company_id and environment='live' for no key update;
 select h.*,o.purchase_purpose,o.amount_baisa,o.currency into g from private.billing_proven_entitlement_grants h join public.billing_orders o on o.id=h.order_id and o.company_id=h.company_id
  where h.id=p_receipt_id and h.company_id=p_company_id and h.provider_environment='live';
 if g.id is null or g.purchase_purpose::text<>'upgrade' or g.amount_baisa<>45000 or g.currency<>'OMR' then return jsonb_build_object('ok',false,'code','UPGRADE_PROOF_REQUIRED');end if;
 execute 'select to_jsonb(b) from private.master_checkout_upgrades b where order_id=$1 and company_id=$2' into b using g.order_id,p_company_id;
 if b is null or (b->>'subscription_id')::uuid<>g.subscription_id or g.previous_paid_through is distinct from (b->>'original_paid_through')::timestamptz
  or g.applied_paid_through is distinct from (b->>'original_paid_through')::timestamptz or (b->>'target_plan_version_id')::uuid<>g.plan_version_id then return jsonb_build_object('ok',false,'code','UPGRADE_PROOF_REQUIRED');end if;
 rid:=private.master_capture_ai_cycle_locked(p_company_id,(b->>'cycle_receipt_id')::uuid,true);target:=(b->>'target_plan_version_id')::uuid;
 select * into c from private.master_ai_cycles where id=rid and company_id=p_company_id for update;
 if c.id is null or c.expires_at is distinct from (b->>'effective_expires_at')::timestamptz or c.starts_at is distinct from (b->>'subscription_started_at')::timestamptz
  or not exists(select 1 from public.billing_plan_versions v join public.billing_plans p on p.id=v.plan_id where v.id=target and p.code='noor_premium' and v.limits->>'automated_outbound_per_month'='1500' and v.amount_baisa=90000 and v.currency='OMR')
 then return jsonb_build_object('ok',false,'code','UPGRADE_PROOF_REQUIRED');end if;
 if exists(select 1 from private.master_ai_credit_grants where source_key='upgrade:'||g.id and cycle_id=rid) then return jsonb_build_object('ok',true,'code','REPLAY','data',jsonb_build_object('cycleId',rid));end if;
 if c.base_cap<>500 or c.current_plan_version_id is distinct from (b->>'prior_plan_version_id')::uuid or c.expires_at<=clock_timestamp() then return jsonb_build_object('ok',false,'code','UPGRADE_PROOF_REQUIRED');end if;
 update private.master_ai_credit_grants x set forfeited=greatest(0,x.units-(select count(*) from private.master_ai_reply_slots s where s.grant_id=x.id and s.state in('held','accepted','unknown'))),replaced=true where cycle_id=rid and kind='base' and not replaced;
 insert into private.master_ai_credit_grants(cycle_id,kind,source_key,units,expires_at) values(rid,'base','upgrade:'||g.id,1500,c.expires_at);
 update private.master_ai_cycles set current_plan_version_id=target,base_cap=1500 where id=rid;
 insert into private.master_ai_credit_events(cycle_id,kind,source_key,detail) values(rid,'upgrade_applied','upgrade:'||g.id,jsonb_build_object('receiptId',g.id,'baseUnits',1500,'expiresAt',c.expires_at));
 return jsonb_build_object('ok',true,'code','APPLIED','data',jsonb_build_object('cycleId',rid,'expiresAt',c.expires_at));
end;$$;

create function private.master_ai_cycle_snapshot(rid uuid) returns jsonb language sql stable security definer set search_path='' as $$
 with c as(select * from private.master_ai_cycles where id=rid), amounts as(
 select k.kind,coalesce(sum(g.units),0) granted,coalesce(sum(s.used),0) consumed,coalesce(sum(s.held),0) held,
 coalesce(sum(case when g.replaced then greatest(0,g.units-s.used-s.held) else g.forfeited end),0) forfeited,
 coalesce(sum(case when g.expires_at<=clock_timestamp() and not g.replaced then greatest(0,g.units-g.forfeited-s.used-s.held) else 0 end),0) expired,
 coalesce(sum(case when g.expires_at>clock_timestamp() and not g.replaced then greatest(0,g.units-g.forfeited-s.used-s.held) else 0 end),0) remaining
 from unnest(array['base','topup','compensation']) k(kind) left join private.master_ai_credit_grants g on g.cycle_id=rid and g.kind=k.kind
 left join lateral(select count(*) filter(where state='accepted') used,count(*) filter(where state in('held','unknown')) held from private.master_ai_reply_slots where grant_id=g.id) s on true group by k.kind)
 select jsonb_build_object('companyId',c.company_id,'cycleId',c.id,'subscriptionId',c.subscription_id,'startsAt',c.starts_at,'expiresAt',c.expires_at,
 'active',c.starts_at<=clock_timestamp() and c.expires_at>clock_timestamp(),'baseCap',c.base_cap,
 'credits',(select jsonb_object_agg(kind,jsonb_build_object('granted',granted,'consumed',consumed,'held',held,'forfeited',forfeited,'expired',expired,'remaining',remaining)) from amounts),
 'totalConsumed',(select sum(consumed) from amounts),'totalRemaining',(select sum(remaining) from amounts),
 'usageNotices',coalesce((select jsonb_agg(jsonb_build_object('threshold',threshold,'state',state) order by threshold) from private.master_ai_usage_notices where cycle_id=rid),'[]'::jsonb),
 'topupConfiguration',case when exists(select 1 from private.master_ai_topup_catalog where enabled) then 'CONFIGURED' else 'UNCONFIGURED' end,
 'compensationConfiguration',case when exists(select 1 from private.master_ai_evidence_contracts where enabled) and exists(select 1 from private.master_ai_credit_legal where nullif(btrim(compensation_expiry_reference),'') is not null) then 'CONFIGURED' else 'UNCONFIGURED' end) from c;
$$;
create function public.master_read_ai_cycle(p_company_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare rid uuid;sid uuid;captured uuid;begin
 if not private.billing_ui_company_owner(p_company_id) or not public.app_session_is_valid() then raise insufficient_privilege;end if;
 begin sid:=(auth.jwt()->>'session_id')::uuid;exception when invalid_text_representation then raise insufficient_privilege;end;
 -- Same canonical lock order as reservation and financial settlement.
 perform 1 from public.companies where id=p_company_id for no key update;
 perform 1 from public.billing_subscriptions where company_id=p_company_id and environment='live' for no key update;
 perform 1 from public.company_members where company_id=p_company_id and user_id=auth.uid() and role='owner' and status='active' for share;if not found then raise insufficient_privilege;end if;
 perform 1 from auth.users where id=auth.uid() and deleted_at is null and (banned_until is null or banned_until<=clock_timestamp()) for share;if not found then raise insufficient_privilege;end if;
 perform 1 from auth.sessions where id=sid and user_id=auth.uid() and (not_after is null or not_after>clock_timestamp()) for share;if not found then raise insufficient_privilege;end if;
 if not private.billing_ui_company_owner(p_company_id) or not public.app_session_is_valid() then raise insufficient_privilege;end if;
 select a.receipt_id into rid from private.master_subscription_activation a where a.company_id=p_company_id and private.master_activation_receipt_current(a.receipt_id) order by a.subscription_started_at desc nulls last,a.receipt_id limit 1;
 if rid is not null and (select enabled from private.master_activation_policy where singleton) then
  captured:=private.master_capture_ai_cycle_locked(p_company_id,rid);
  if captured is null then return jsonb_build_object('ok',false,'code','CYCLE_ACCOUNTING_REVIEW_REQUIRED');end if;rid:=captured;
 end if;
 if rid is null or not exists(select 1 from private.master_ai_cycles where id=rid) then
  -- Expired cycles remain visible history, with zero usable credits.
  select id into rid from private.master_ai_cycles where company_id=p_company_id order by starts_at desc,id limit 1;
 end if;
 return case when rid is null then jsonb_build_object('ok',false,'code','CYCLE_UNAVAILABLE') else jsonb_build_object('ok',true,'data',private.master_ai_cycle_snapshot(rid)) end;
end;$$;

create function public.master_apply_ai_topup(p_company_id uuid,p_receipt_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare g record;t private.master_ai_topup_contracts;k private.master_ai_topup_catalog;c private.master_ai_cycles;begin
 if current_setting('role',true)<>'service_role' then raise insufficient_privilege;end if;
 if not exists(select 1 from private.master_ai_topup_catalog where enabled) then return jsonb_build_object('ok',false,'code','UNCONFIGURED');end if;
 perform 1 from public.companies where id=p_company_id for no key update;perform 1 from public.billing_subscriptions where company_id=p_company_id and environment='live' for no key update;
 select h.*,o.purchase_purpose,o.amount_baisa,o.currency into g from private.billing_proven_entitlement_grants h join public.billing_orders o on o.id=h.order_id and o.company_id=h.company_id where h.id=p_receipt_id and h.company_id=p_company_id and h.provider_environment='live';
 if g.id is null or g.purchase_purpose::text<>'topup' then return jsonb_build_object('ok',false,'code','TOPUP_PAYMENT_PROOF_REQUIRED');end if;
 select * into t from private.master_ai_topup_contracts where order_id=g.order_id;select * into k from private.master_ai_topup_catalog where sku=t.sku and enabled;
 select * into c from private.master_ai_cycles where id=t.cycle_id and company_id=p_company_id for update;
 if c.id is null or k.sku is null or g.subscription_id is distinct from c.subscription_id or g.plan_version_id is distinct from k.plan_version_id
  or g.currency<>'OMR' or g.amount_baisa<>k.amount_baisa or g.previous_paid_through is distinct from g.applied_paid_through
  or t.expires_at is distinct from c.expires_at or t.terms_reference<>k.legal_reference or t.accepted_at>g.applied_at or t.accepted_at<c.starts_at
  or not exists(select 1 from public.company_members where company_id=p_company_id and user_id=t.accepted_by and role='owner' and status='active')
 then return jsonb_build_object('ok',false,'code','TOPUP_PAYMENT_PROOF_REQUIRED');end if;
 if exists(select 1 from private.master_ai_credit_grants where source_key='topup:'||g.id and cycle_id=c.id) then return jsonb_build_object('ok',true,'code','REPLAY');end if;
 insert into private.master_ai_credit_grants(cycle_id,kind,source_key,units,expires_at) values(c.id,'topup','topup:'||g.id,k.units,c.expires_at);
 insert into private.master_ai_credit_events(cycle_id,kind,source_key,detail) values(c.id,'topup_applied','topup:'||g.id,jsonb_build_object('receiptId',g.id,'sku',k.sku,'units',k.units,'expiresAt',c.expires_at));
 return jsonb_build_object('ok',true,'code','APPLIED');
end;$$;

-- Trusted incident collector port only. Approval enables an authenticated
-- server producer, never customer-supplied outage duration or reply counts.
create function public.master_record_ai_cycle_evidence(p_company_id uuid,p_cycle_id uuid,p_source text,p_evidence_reference text,p_kind text,p_channels text[],p_starts_at timestamptz,p_ends_at timestamptz) returns jsonb
language plpgsql security definer set search_path='' as $$declare c private.master_ai_cycles;chosen text[];entitled integer;oid uuid;prior private.master_ai_observations;begin
 if current_setting('role',true)<>'service_role' then raise insufficient_privilege;end if;
 if not exists(select 1 from private.master_ai_evidence_contracts where source=p_source and enabled) then return jsonb_build_object('ok',false,'code','UNCONFIGURED');end if;
 perform 1 from public.companies where id=p_company_id for no key update;perform 1 from public.billing_subscriptions where company_id=p_company_id and environment='live' for no key update;
 select * into c from private.master_ai_cycles where id=p_cycle_id and company_id=p_company_id for update;
 if c.id is null or p_kind is null or p_kind not in('healthy','outage','incomplete') or p_evidence_reference is null or length(btrim(p_evidence_reference)) not between 1 and 200
  or p_starts_at is null or p_ends_at is null or not isfinite(p_starts_at) or not isfinite(p_ends_at) or p_ends_at<=p_starts_at or p_ends_at>clock_timestamp()
  or p_starts_at<c.starts_at or p_ends_at>c.expires_at then return jsonb_build_object('ok',false,'code','INVALID_EVIDENCE');end if;
 select array_agg(x order by x) into chosen from private.company_selected_channels s cross join lateral unnest(s.channels) x where s.company_id=p_company_id and s.plan_version_id=c.current_plan_version_id;
 select channel_count into entitled from private.plan_channel_entitlements where plan_version_id=c.current_plan_version_id;
 if chosen is null or entitled is null or cardinality(chosen)<>entitled or p_channels is null or (select array_agg(distinct x order by x) from unnest(p_channels) x) is distinct from chosen or cardinality(p_channels)<>cardinality(chosen)
 then return jsonb_build_object('ok',false,'code','ALL_SELECTED_CHANNELS_REQUIRED');end if;
 select * into prior from private.master_ai_observations where evidence_reference=p_evidence_reference;
 if prior.id is not null then
  if row(prior.cycle_id,prior.source,prior.kind,prior.channels,prior.starts_at,prior.ends_at) is distinct from row(c.id,p_source,p_kind,chosen,p_starts_at,p_ends_at) then return jsonb_build_object('ok',false,'code','EVIDENCE_REPLAY_CONFLICT');end if;
  return jsonb_build_object('ok',true,'code','REPLAY','data',jsonb_build_object('observationId',prior.id));end if;
 -- Complete disjoint coverage prevents duplicate time and contradictory spans.
 if exists(select 1 from private.master_ai_observations where cycle_id=c.id and starts_at<p_ends_at and ends_at>p_starts_at) then return jsonb_build_object('ok',false,'code','EVIDENCE_OVERLAP_REVIEW_REQUIRED');end if;
 insert into private.master_ai_observations(cycle_id,source,evidence_reference,kind,channels,starts_at,ends_at) values(c.id,p_source,p_evidence_reference,p_kind,chosen,p_starts_at,p_ends_at) returning id into oid;
 return jsonb_build_object('ok',true,'data',jsonb_build_object('observationId',oid));
end;$$;

create function public.master_assess_ai_compensation(p_company_id uuid,p_observation_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare o private.master_ai_observations;c private.master_ai_cycles;healthy_secs numeric;replies bigint;estimate numeric:=0;award bigint;remaining bigint;tz text;missing boolean;outcome text;prior private.master_ai_compensation_assessments;begin
 if current_setting('role',true)<>'service_role' then raise insufficient_privilege;end if;
 perform 1 from public.companies where id=p_company_id for no key update;perform 1 from public.billing_subscriptions where company_id=p_company_id and environment='live' for no key update;
 select * into o from private.master_ai_observations where id=p_observation_id;select * into c from private.master_ai_cycles where id=o.cycle_id and company_id=p_company_id for update;
 if c.id is null or o.kind<>'outage' or o.ends_at-o.starts_at<interval '1 hour' or o.starts_at<c.starts_at or o.ends_at>c.expires_at then return jsonb_build_object('ok',false,'code','OUTAGE_INELIGIBLE');end if;
 select * into prior from private.master_ai_compensation_assessments where observation_id=o.id;
 if prior.observation_id is not null then return jsonb_build_object('ok',true,'code','REPLAY','data',jsonb_build_object('awardedUnits',prior.awarded_units,'outcome',prior.outcome));end if;
 if not exists(select 1 from private.master_ai_evidence_contracts where source=o.source and enabled) then return jsonb_build_object('ok',false,'code','UNCONFIGURED');end if;
 if not exists(select 1 from private.master_ai_credit_legal where nullif(btrim(compensation_expiry_reference),'') is not null) then return jsonb_build_object('ok',false,'code','LEGAL_REVIEW_REQUIRED');end if;
 select coalesce(sum(extract(epoch from ends_at-starts_at)),0) into healthy_secs from private.master_ai_observations where cycle_id=c.id and kind='healthy' and channels=o.channels and ends_at<=o.starts_at;
 select count(*) into replies from private.master_ai_reply_slots s join public.ai_usage_ledger a on a.id=s.ai_attempt_id and a.company_id=s.company_id and a.usage_mode='company_live' and a.status='success' and nullif(btrim(a.request_id),'') is not null
  where s.cycle_id=c.id and s.state='accepted' and s.accepted_at<o.starts_at and s.accepted_at>=c.starts_at and not exists(select 1 from public.whatsapp_messages m join public.whatsapp_send_intents i on i.message_id=m.id where i.id=s.native_intent_id and m.delivery_state='failed');
 if healthy_secs<7*86400 or replies<30 then outcome:='INSUFFICIENT_ACTUAL_HISTORY';else
  select x.timezone into tz from public.companies x where id=p_company_id and exists(select 1 from pg_timezone_names where name=x.timezone);
  if tz is null then return jsonb_build_object('ok',false,'code','COMPARISON_TIMEZONE_UNCONFIGURED');end if;
  -- Exact complete duration, split on UTC minute boundaries (preserves local
  -- hour boundaries even in half/quarter-hour zones). No maximum-duration clamp.
  with coverage as materialized(select extract(isodow from t at time zone tz) dow,extract(hour from t at time zone tz) hr,
   sum(extract(epoch from least(t+interval '1 minute',h.ends_at)-greatest(t,h.starts_at))) secs
   from private.master_ai_observations h cross join lateral generate_series(date_trunc('minute',h.starts_at),h.ends_at-interval '1 microsecond',interval '1 minute') t where h.cycle_id=c.id and h.kind='healthy' and h.channels=o.channels and h.ends_at<=o.starts_at group by 1,2),
  samples as materialized(select extract(isodow from s.accepted_at at time zone tz) dow,extract(hour from s.accepted_at at time zone tz) hr,count(*) n
   from private.master_ai_reply_slots s join public.ai_usage_ledger a on a.id=s.ai_attempt_id where s.cycle_id=c.id and s.state='accepted' and a.usage_mode='company_live' and a.status='success' and nullif(btrim(a.request_id),'') is not null
   and exists(select 1 from private.master_ai_observations h where h.cycle_id=c.id and h.kind='healthy' and h.channels=o.channels and h.ends_at<=o.starts_at and s.accepted_at>=h.starts_at and s.accepted_at<h.ends_at)
   and not exists(select 1 from public.whatsapp_messages m join public.whatsapp_send_intents i on i.message_id=m.id where i.id=s.native_intent_id and m.delivery_state='failed') group by 1,2),
  lost as(select extract(isodow from t at time zone tz) dow,extract(hour from t at time zone tz) hr,sum(extract(epoch from least(t+interval '1 minute',o.ends_at)-greatest(t,o.starts_at))) secs
   from generate_series(date_trunc('minute',o.starts_at),o.ends_at-interval '1 microsecond',interval '1 minute') t group by 1,2)
  select coalesce(sum(l.secs*coalesce(s.n,0)/nullif(h.secs,0)),0),coalesce(bool_or(h.secs is null or h.secs<=0),true) into estimate,missing from lost l left join coverage h using(dow,hr) left join samples s using(dow,hr);
  if missing then outcome:='INSUFFICIENT_COMPARABLE_HISTORY';end if;
 end if;
 select greatest(0,c.base_cap/10-coalesce(sum(units),0)) into remaining from private.master_ai_credit_grants where cycle_id=c.id and kind='compensation';
 award:=case when outcome is null then least(remaining,floor(estimate)::bigint) else 0 end;outcome:=coalesce(outcome,case when remaining=0 then 'CYCLE_CAP_REACHED' when award=0 then 'NO_ESTIMATED_LOSS' when c.expires_at<=clock_timestamp() then 'AWARDED_EXPIRED' else 'AWARDED' end);
 insert into private.master_ai_compensation_assessments values(o.id,c.id,estimate,award,outcome,clock_timestamp());
 if award>0 then insert into private.master_ai_credit_grants(cycle_id,kind,source_key,units,expires_at) values(c.id,'compensation','compensation:'||o.id,award,c.expires_at);end if;
 insert into private.master_ai_credit_events(cycle_id,kind,source_key,detail) values(c.id,'compensation_assessed','compensation:'||o.id,jsonb_build_object('observationId',o.id,'estimatedUnits',estimate,'awardedUnits',award,'outcome',outcome,'expiresAt',c.expires_at));
 return jsonb_build_object('ok',true,'data',jsonb_build_object('awardedUnits',award,'estimatedUnits',estimate,'outcome',outcome));
end;$$;

create function public.master_ai_cycle_costs(p_company_id uuid,p_cycle_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare c private.master_ai_cycles;d jsonb;begin
 if current_setting('role',true)<>'service_role' then raise insufficient_privilege;end if;
 select * into c from private.master_ai_cycles where id=p_cycle_id and company_id=p_company_id;if c.id is null then return jsonb_build_object('ok',false,'code','CYCLE_UNAVAILABLE');end if;
 select coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) into d from(select a.model_id model,s.channel,g.kind category,count(distinct a.id) attempts,coalesce(sum(a.cost_baisa),0) estimated_baisa
  from public.ai_usage_ledger a left join private.master_ai_attempt_credit_binding b on b.attempt_id=a.id and b.company_id=a.company_id left join private.master_ai_reply_slots s on s.job_id=b.job_id and s.company_id=b.company_id left join private.master_ai_credit_grants g on g.id=b.grant_id
  where a.company_id=p_company_id and a.usage_mode='company_live' and a.created_at>=c.starts_at and a.created_at<c.expires_at group by a.model_id,s.channel,g.kind) x;
 return jsonb_build_object('ok',true,'data',jsonb_build_object('basis','native_usage_tariff_estimate','providerFinalCost',null,'groups',d));
end;$$;

-- No native Instagram AI generation/accepted-usage engine currently exists.
-- Paired ports deliberately deny both capacity and dispatch until that exact
-- native engine has immutable job, claim, receipt and cost-ledger integration.
create function public.master_reserve_instagram_ai_credit(p_company_id uuid,p_job_id uuid,p_claim_token uuid) returns jsonb language plpgsql security definer set search_path='' as $$begin
 if current_setting('role',true)<>'service_role' then raise insufficient_privilege;end if;return jsonb_build_object('ok',false,'code','INSTAGRAM_AI_UNCONFIGURED');end;$$;
create function public.master_authorize_instagram_ai_dispatch(p_company_id uuid,p_job_id uuid,p_claim_token uuid) returns jsonb language plpgsql security definer set search_path='' as $$begin
 if current_setting('role',true)<>'service_role' then raise insufficient_privilege;end if;return jsonb_build_object('ok',false,'code','INSTAGRAM_AI_UNCONFIGURED');end;$$;

-- Native stage/model/send guards use the same proven cycle start, without
-- changing the separately enforced native provider-cost budgets.
do $$declare fn record;d text;updated text;stages integer:=0;sends integer:=0;models integer:=0;authorities integer:=0;begin
 for fn in select p.oid,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('private','public') and (p.proname like '%stage_job_reply%' or p.proname='wa_stage_pre_answer_profile' or p.proname like '%claim_assistant_job_send%' or p.proname='wa_claim_assistant_pre_meta_policy' or p.proname='ai_lock_authorized_whatsapp_job' or p.proname='wa_noura_authority') loop
  d:=pg_get_functiondef(fn.oid);updated:=replace(d,'private.wa_worker_month()','private.master_ai_cycle_period(j.company_id)');
  updated:=replace(updated,'(date_trunc(''month'',clock_timestamp() at time zone ''Asia/Muscat'') at time zone ''Asia/Muscat'')','private.master_ai_cycle_period(j.company_id)');
  if updated=d then continue;end if;
  if fn.proname like '%stage_job_reply%' or fn.proname='wa_stage_pre_answer_profile' then stages:=stages+1;elsif fn.proname like '%claim_assistant_job_send%' or fn.proname='wa_claim_assistant_pre_meta_policy' then sends:=sends+1;elsif fn.proname='ai_lock_authorized_whatsapp_job' then models:=models+1;elsif fn.proname='wa_noura_authority' then authorities:=authorities+1;end if;execute updated;
 end loop;
 if stages<1 or sends<1 or models<>1 or authorities<>1 then raise exception 'CYCLE_NATIVE_PERIOD_PREREQUISITE_MISSING';end if;
end;$$;
create function private.master_ai_job_has_credit(p_job uuid) returns boolean language sql volatile security definer set search_path='' as $$
 select not (select enabled from private.master_activation_policy where singleton) or exists(select 1 from private.master_ai_reply_slots s join private.master_ai_cycles c on c.id=s.cycle_id join public.whatsapp_inbound_jobs j on j.id=s.job_id where s.job_id=p_job and s.company_id=j.company_id and s.state='held' and c.starts_at<=clock_timestamp() and c.expires_at>clock_timestamp() and j.usage_subscription_id=c.subscription_id and j.usage_period_start=c.starts_at);
$$;
-- Capacity, model execution, staging and provider dispatch share the same slot.
alter function private.ai_lock_authorized_whatsapp_job(uuid,uuid,integer) rename to master_pre_cycle_ai_job_guard;
create function private.ai_lock_authorized_whatsapp_job(p_job_id uuid,p_claim_token uuid,p_generation integer default null) returns jsonb language plpgsql security definer set search_path='' as $$declare r jsonb;begin
 r:=private.master_pre_cycle_ai_job_guard(p_job_id,p_claim_token,p_generation);if r->>'ok' is distinct from 'true' then return r;end if;
 if not private.master_ai_job_has_credit(p_job_id) then return jsonb_build_object('ok',false,'code','CYCLE_CREDIT_RESERVATION_REQUIRED');end if;return r;end;$$;
do $$declare fn record;d text;anchor text:='or j.usage_status is distinct from ''reserved''';begin
 for fn in select p.oid from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('private','public') and (p.proname like '%stage_job_reply%' or p.proname like '%claim_assistant_job_send%') loop
 d:=pg_get_functiondef(fn.oid);if strpos(d,anchor)>0 then execute replace(d,anchor,'or not private.master_ai_job_has_credit(j.id) '||anchor);end if;end loop;
end;$$;
revoke all on function private.master_ai_cycle_period(uuid),private.master_capture_ai_cycle_locked(uuid,uuid,boolean),private.master_sync_ai_reply(uuid),private.master_sync_ai_reply_trigger(),public.master_capture_ai_cycle(uuid,uuid),public.master_apply_cycle_upgrade(uuid,uuid),public.whatsapp_reserve_job_usage(uuid,uuid) from public,anon,authenticated,service_role;
grant execute on function public.master_capture_ai_cycle(uuid,uuid),public.master_apply_cycle_upgrade(uuid,uuid),public.whatsapp_reserve_job_usage(uuid,uuid) to service_role;
revoke all on function private.master_ai_cycle_snapshot(uuid),private.master_ai_job_has_credit(uuid),private.master_pre_cycle_ai_job_guard(uuid,uuid,integer),private.ai_lock_authorized_whatsapp_job(uuid,uuid,integer),public.master_read_ai_cycle(uuid),public.master_apply_ai_topup(uuid,uuid),public.master_record_ai_cycle_evidence(uuid,uuid,text,text,text,text[],timestamptz,timestamptz),public.master_assess_ai_compensation(uuid,uuid),public.master_ai_cycle_costs(uuid,uuid),public.master_reserve_instagram_ai_credit(uuid,uuid,uuid),public.master_authorize_instagram_ai_dispatch(uuid,uuid,uuid) from public,anon,authenticated,service_role;
revoke all on function private.master_ai_attempt_binding_trigger() from public,anon,authenticated,service_role;
grant execute on function public.master_read_ai_cycle(uuid) to authenticated;
grant execute on function private.ai_lock_authorized_whatsapp_job(uuid,uuid,integer),public.master_apply_ai_topup(uuid,uuid),public.master_record_ai_cycle_evidence(uuid,uuid,text,text,text,text[],timestamptz,timestamptz),public.master_assess_ai_compensation(uuid,uuid),public.master_ai_cycle_costs(uuid,uuid),public.master_reserve_instagram_ai_credit(uuid,uuid,uuid),public.master_authorize_instagram_ai_dispatch(uuid,uuid,uuid) to service_role;
-- Short transactional gates do not benefit from per-call JIT compilation.
do $$declare f record;begin for f in select p.oid from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('private','public') and (p.proname like 'master_%ai%' or p.proname='master_apply_cycle_upgrade' or p.proname='whatsapp_reserve_job_usage' or p.proname='ai_lock_authorized_whatsapp_job') loop execute format('alter function %s set jit=off',f.oid::regprocedure);end loop;end;$$;
commit;
